function LadderCompetionBattleRecordCellNode:RefreshData_()
    ---@type LadderRecordDojo
    local cellData = self:GetCellData()
    local myData = cellData:GetMyData()
    local otherData = cellData:GetOtherData()
    -- print("[记录]", table.dump(myData, nil, 3), table.dump(otherData, nil, 3))

    CfUtils.SetUISwitchImage(self.winIcon.gameObject, myData.win == true and 1 or 2)
            
    --score
    --local score = cellData.mainScore
    --if cellData.isMainWin == true then
    --    score = score - cellData.mainDiffScore
    --else
    --    score = score + cellData.mainDiffScore
    --end
    CfUtils.FillText(self.TxtNumber, "")
    local sign = myData.win == true and '+' or '-'
    self.TxtNumberChange.Status = myData.win == true and 1 or 2
    CfUtils.FillText(self.TxtNumberChange, string.format("%s%d", sign, myData.diffScore))
    
    --self
    local ladderCompetionUtils = import("Game.UI.LadderCompetion.LadderCompetionUtils")
    local gradeVo = ladderCompetionUtils.GetGradeVo(myData.segment, myData.subSegment)
    CfUtils.FillImage(self.ImgSelfSegment, gradeVo.icon)

    local starCount = checkNumber(myData.subSegment)
    for i = 1, 5 do
        local child = self.SelfStarGroup.transform:GetChild(i - 1)
        if i <= starCount then
            KTool.SetActive(child.gameObject,true)
        else
            KTool.SetActive(child.gameObject,false)
        end
    end
    
    local selfCardsCount = #myData.team > 0 and #myData.team[1] or 0
    for index = 1,4 do
        if index <= selfCardsCount then
            CfUtils.RefeshCommonSmallHeroGo(self.selfCardGroup[index], myData.team[1][index])
            KTool.SetActive(self.selfEmptyGroup[index],false)
        else
            KTool.SetActive(self.selfCardGroup[index],false)
            KTool.SetActive(self.selfEmptyGroup[index],true)
        end
    end
    
    local selfCombatVal = 0
    if selfCardsCount > 0 then
        for i = 1, selfCardsCount do
            selfCombatVal = selfCombatVal + checkNumber(myData.team[1][i].combatValue)
        end
    end
    CfUtils.FillText(self.TxtSelfPowerNum, selfCombatVal)
    
    --enemy
    ---@type PlayerDojo
    local playerDojo = playerComponent:GetPlayerDojo()
    local myId = playerDojo.playerId
    for k,v in pairs(cellData.campDesc) do
        if checkNumber(k) ~= checkNumber(myId) then
            local data = checkTable(v)
            CfUtils.FillText(self.TxtEnemyName, data.name)
        end
    end

    local gradeVo1
    local enemySubSegment
    local ladderCompetionUtils = import("Game.UI.LadderCompetion.LadderCompetionUtils")
    if cellData.robotId == 0 then
        gradeVo1 = ladderCompetionUtils.GetGradeVo(otherData.segment, otherData.subSegment)
        enemySubSegment = otherData.subSegment
    else
        ---@type LadderRobotVo
        local robotVo = CfUtils.GetCfVo(AutoIds.IdSetting2566, "LadderRobotVo", cellData.robotId) or {}
        gradeVo1 = ladderCompetionUtils.GetGradeVo(robotVo.grade, robotVo.starPVP)
        enemySubSegment = checkInt(robotVo.starPVP)
    end
    CfUtils.FillImage(self.ImgEnemySegment, gradeVo1.icon)

    local starCount1 = checkNumber(enemySubSegment)
    for i = 1, 5 do
        local child = self.EnemyStarGroup.transform:GetChild(i - 1)
        if i <= starCount1 then
            KTool.SetActive(child.gameObject,true)
        else
            KTool.SetActive(child.gameObject,false)
        end
    end

    local enemyCardsCount = #otherData.team > 0 and #otherData.team[1] or 0
    for index = 1,4 do
        if index <= enemyCardsCount then
            CfUtils.RefeshCommonSmallHeroGo(self.enemyCardGroup[index],otherData.team[1][index])
            KTool.SetActive(self.enemyEmptyGroup[index],false)
        else
            KTool.SetActive(self.enemyCardGroup[index],false)
            KTool.SetActive(self.enemyEmptyGroup[index],true)
        end
    end

    local enemyCombatVal = 0
    if enemyCardsCount > 0 then
        for i = 1, enemyCardsCount do
            enemyCombatVal = enemyCombatVal + checkNumber(otherData.team[1][i].combatValue)
        end
    end
    CfUtils.FillText(self.TxtEnemyPowerNum, enemyCombatVal)

    if isNotNull(cellData.time) then
        CfUtils.FillText(self.TxtTime, cellData.time)
    end
end

return LadderCompetionBattleRecordCellNode